<?php require __DIR__ . '/includes/config.php'; $id=(int)($_GET['id']??0); $statement=$pdo->prepare('SELECT p.*, c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=?');$statement->execute([$id]);$product=$statement->fetch();if(!$product){redirect('index.php');} if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??'cart'; if($action==='wishlist'){$_SESSION['wishlist'][$id]=true;flash('success','Added to your wishlist.');redirect('wishlist.php');} $_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+(int)($_POST['quantity']??1);flash('success','Added to cart.');redirect($action==='buy'?'checkout.php':'cart.php');} $pageTitle=$product['name'];require __DIR__ . '/includes/header.php'; ?>
<section class="container py-5"><div class="row g-5 align-items-center"><div class="col-md-6"><img class="img-fluid" src="<?= e($product['image']) ?>" alt="<?= e($product['name']) ?>"></div><div class="col-md-5"><div class="tag mb-3"><?= e($product['category']) ?></div><h1 class="display-5"><?= e($product['name']) ?></h1><div class="price fs-4 my-4">$<?= number_format((float)$product['price'],2) ?></div><p class="lead text-secondary"><?= e($product['description']) ?></p><form method="post" class="d-flex gap-2 align-items-center mt-4"><input class="form-control" style="max-width:90px" type="number" min="1" max="<?= (int)$product['stock'] ?>" name="quantity" value="1"><button name="action" value="cart" class="btn btn-dark flex-grow-1">Add to cart</button><button name="action" value="buy" class="btn btn-accent">Buy now</button></form><form method="post" class="mt-2"><button name="action" value="wishlist" class="btn btn-link text-dark px-0">♡ Add to wishlist</button></form></div></div></section><?php require __DIR__ . '/includes/footer.php'; ?>